      "text": "; @module   graphics\n; @summary  PLOT, DRAW (straight lines) and CIRCLE: Klive's own pixel routines.\n; @exports  Plot, DrawLine, Circle\n; @requires print, errors\n; @abi      Plot(c, b)\n; @abi      DrawLine(de, hl)\n; @abi      Circle(d, e, c)\n;\n; The screen is 256 x 192 pixels with (0,0) at the bottom left; all 192 rows are usable (the ROM\n; keeps the bottom 16 for its editor). A pixel follows the current colours: OVER flips it, INVERSE\n; clears it, both leave it alone; its cell takes the colours as PRINT gives them (PrintApplyAttr).\n; COORDS ($5C7D x, $5C7E y) is the last point plotted: DRAW starts there. A point off the screen is\n; not drawn - PLOT plots nothing, DRAW nothing at all when its end is off, CIRCLE skips it - and\n; ERR_NR becomes 4 (\"5 Out of screen\") while the program carries on, as ZX BASIC does\n; (compatibility plan C3).\n\n; ------------------------------------------------------------------------------------------------\n; PLOT: C = x, B = y. Changes AF, BC, DE, HL.\nPlot:\n    ld a,b\n    cp 192\n    jr nc,GraphicsRange\n    ld ($5c7d),bc           ; COORDS\n    call PixelAddr          ; HL = the byte, A = the pixel's bit\n    ld d,a\n    ld a,(PrintFlags)\n    ld e,a\n    bit 1,e\n    jr z,PlotNotInverse\n    bit 0,e\n    jr nz,PlotAttr          ; INVERSE and OVER: the pixel stays as it is\n    ld a,d\n    cpl\n    and (hl)\n    jr PlotStore\nPlotNotInverse:\n    ld a,d\n    bit 0,e\n    jr z,PlotSet\n    xor (hl)\n    jr PlotStore\nPlotSet:\n    or (hl)\nPlotStore:\n    ld (hl),a\nPlotAttr:\n    ld a,h                  ; the pixel byte's attribute: $5800 + (the third) * 256 + L\n    rrca\n    rrca\n    rrca\n    and $03\n    or $58\n    ld h,a\n    jp PrintApplyAttr\n\nGraphicsRange:              ; reached before anything is pushed: returns to the statement\n    ld a,4                  ; \"5 Out of screen\"\n    ld ($5c3a),a            ; ERR_NR\n    ret\n\n; HL = the screen byte of pixel (C, B), y counted from the bottom (0-191); A = its bit. Keeps BC.\n; Changes F, DE.\nPixelAddr:\n    ld a,191\n    sub b\n    ld d,a                  ; D = the row from the top: r7 r6 r5 r4 r3 r2 r1 r0\n    and $07\n    ld h,a\n    ld a,d\n    and $c0\n    rrca\n    rrca\n    rrca\n    or h\n    or $40\n    ld h,a                  ; H = 0 1 0 r7 r6 r2 r1 r0\n    ld a,d\n    and $38\n    rlca\n    rlca\n    ld l,a\n    ld a,c\n    rrca\n    rrca\n    rrca\n    and $1f\n    or l\n    ld l,a                  ; L = r5 r4 r3 x7 x6 x5 x4 x3\n    ld a,c\n    and $07\n    ld e,a\n    ld a,$80\n    ret z\nPixelMask:\n    rrca\n    dec e\n    jr nz,PixelMask\n    ret\n\n; ------------------------------------------------------------------------------------------------\n; DRAW dx, dy: a straight line from COORDS to COORDS + (DE, HL), every point but the first plotted\n; (Bresenham). The end point is checked before anything is drawn. Changes AF, BC, DE, HL.\nDrawLine:\n    ld (DrawDx),de\n    ld (DrawDy),hl\n    ld a,($5c7e)\n    ld c,a\n    ld b,0\n    add hl,bc               ; HL = the end's y\n    ld a,h\n    or a\n    jr nz,GraphicsRange\n    ld a,l\n    cp 192\n    jr nc,GraphicsRange\n    ld a,($5c7d)\n    ld l,a\n    ld h,0\n    add hl,de               ; HL = the end's x\n    ld a,h\n    or a\n    jr nz,GraphicsRange\n    ld hl,(DrawDx)\n    call DrawAbs\n    ld (DrawAx),a\n    ld a,b\n    ld (DrawSx),a\n    ld hl,(DrawDy)\n    call DrawAbs\n    ld (DrawAy),a\n    ld a,b\n    ld (DrawSy),a\n    ld bc,($5c7d)           ; C = x, B = y\n    ld a,(DrawAy)\n    ld d,a\n    ld a,(DrawAx)\n    cp d\n    jr c,DrawSteep\n    ; --- |dx| >= |dy|: a step in x every time, in y when the error runs out\n    or a\n    ret z\n    ld (DrawCount),a\n    srl a\n    ld l,a\n    ld h,0\n    ld (DrawErr),hl\nDrawShallow:\n    ld a,(DrawSx)\n    add a,c\n    ld c,a\n    ld hl,(DrawErr)\n    ld a,(DrawAy)\n    ld e,a\n    ld d,0\n    or a\n    sbc hl,de\n    bit 7,h\n    jr z,DrawShallowPlot\n    ld a,(DrawSy)\n    add a,b\n    ld b,a\n    ld a,(DrawAx)\n    ld e,a\n    add hl,de\nDrawShallowPlot:\n    ld (DrawErr),hl\n    push bc\n    call Plot\n    pop bc\n    ld hl,DrawCount\n    dec (hl)\n    jr nz,DrawShallow\n    ret\nDrawSteep:                  ; |dy| > |dx|: a step in y every time\n    ld a,d\n    ld (DrawCount),a\n    srl a\n    ld l,a\n    ld h,0\n    ld (DrawErr),hl\nDrawSteepLoop:\n    ld a,(DrawSy)\n    add a,b\n    ld b,a\n    ld hl,(DrawErr)\n    ld a,(DrawAx)\n    ld e,a\n    ld d,0\n    or a\n    sbc hl,de\n    bit 7,h\n    jr z,DrawSteepPlot\n    ld a,(DrawSx)\n    add a,c\n    ld c,a\n    ld a,(DrawAy)\n    ld e,a\n    add hl,de\nDrawSteepPlot:\n    ld (DrawErr),hl\n    push bc\n    call Plot\n    pop bc\n    ld hl,DrawCount\n    dec (hl)\n    jr nz,DrawSteepLoop\n    ret\n\n; A = |HL| (at most 255 here), B = the step: 1, $FF (-1) or 0. Changes F.\nDrawAbs:\n    ld b,0\n    ld a,h\n    or l\n    ret z\n    ld b,1\n    ld a,l\n    bit 7,h\n    ret z\n    ld b,$ff\n    neg\n    ret\n\nDrawDx:\n    .defw 0\nDrawDy:\n    .defw 0\nDrawAx:\n    .defb 0\nDrawAy:\n    .defb 0\nDrawSx:\n    .defb 0\nDrawSy:\n    .defb 0\nDrawErr:\n    .defw 0\nDrawCount:\n    .defb 0\n\n; ------------------------------------------------------------------------------------------------\n; CIRCLE: D = the centre's x, E = its y, C = the radius (all 0-255). The midpoint method, every\n; point plotted once, so that OVER 1 leaves no gaps. Changes AF, BC, DE, HL.\nCircle:\n    ld a,c\n    ld (CircleR),a\n    ld a,d\n    ld (CircleCx),a\n    ld a,e\n    ld (CircleCy),a\n    ld a,(CircleR)\n    ld (CircleX),a\n    xor a\n    ld (CircleY),a\n    ld a,(CircleR)\n    ld e,a\n    ld d,0\n    ld hl,1\n    or a\n    sbc hl,de\n    ld (CircleErr),hl       ; err = 1 - r\nCircleLoop:\n    ld a,(CircleY)\n    ld b,a\n    ld a,(CircleX)\n    cp b\n    ret c                   ; x < y: the octant is done\n    ld (CircleA),a\n    ld a,b\n    ld (CircleB),a\n    call CirclePlot4        ; (±x, ±y)\n    ld a,(CircleX)\n    ld b,a\n    ld a,(CircleY)\n    cp b\n    jr z,CircleStep         ; x = y: (±y, ±x) are the same points\n    ld (CircleA),a\n    ld a,b\n    ld (CircleB),a\n    call CirclePlot4        ; (±y, ±x)\nCircleStep:\n    ld a,(CircleX)\n    or a\n    ret z                   ; radius 0: the centre alone\n    ld hl,CircleY\n    inc (hl)\n    ld hl,(CircleErr)\n    ld a,(CircleY)\n    ld e,a\n    ld d,0\n    bit 7,h\n    jr z,CircleInward\n    add hl,de               ; err += 2y + 1\n    add hl,de\n    inc hl\n    ld (CircleErr),hl\n    jr CircleLoop\nCircleInward:\n    ld a,(CircleX)          ; x -= 1; err += 2(y - x) + 1\n    dec a\n    ld (CircleX),a\n    add hl,de\n    add hl,de\n    ld e,a\n    or a\n    sbc hl,de\n    or a\n    sbc hl,de\n    inc hl\n    ld (CircleErr),hl\n    jr CircleLoop\n\n; Plots (cx ± a, cy ± b) for CircleA = a, CircleB = b, each distinct point once.\nCirclePlot4:\n    ld c,0\n    call CirclePlotSigned   ; (+a, +b)\n    ld a,(CircleA)\n    or a\n    jr z,CirclePlot4Lower\n    ld c,1\n    call CirclePlotSigned   ; (-a, +b)\nCirclePlot4Lower:\n    ld a,(CircleB)\n    or a\n    ret z\n    ld c,2\n    call CirclePlotSigned   ; (+a, -b)\n    ld a,(CircleA)\n    or a\n    ret z\n    ld c,3                  ; (-a, -b)\nCirclePlotSigned:           ; C: bit 0 subtracts a, bit 1 subtracts b\n    ld a,(CircleCx)\n    ld l,a\n    ld h,0\n    ld a,(CircleA)\n    ld e,a\n    ld d,0\n    bit 0,c\n    jr nz,CircleLeft\n    add hl,de\n    jr CircleXDone\nCircleLeft:\n    or a\n    sbc hl,de\nCircleXDone:\n    ld a,h\n    or a\n    jp nz,GraphicsRange\n    ld a,l\n    ld (CirclePx),a\n    ld a,(CircleCy)\n    ld l,a\n    ld h,0\n    ld a,(CircleB)\n    ld e,a\n    bit 1,c\n    jr nz,CircleDown\n    add hl,de\n    jr CircleYDone\nCircleDown:\n    or a\n    sbc hl,de\nCircleYDone:\n    ld a,h\n    or a\n    jp nz,GraphicsRange\n    ld b,l\n    ld a,(CirclePx)\n    ld c,a\n    jp Plot\n\nCircleR:\n    .defb 0\nCircleCx:\n    .defb 0\nCircleCy:\n    .defb 0\nCircleX:\n    .defb 0\nCircleY:\n    .defb 0\nCircleA:\n    .defb 0\nCircleB:\n    .defb 0\nCirclePx:\n    .defb 0\nCircleErr:\n    .defw 0\n"
